<script setup lang="ts">import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';import {Head,Link} from '@inertiajs/vue3';import axios from 'axios';import{ref}from'vue';const props=defineProps<{profileUser:any,posts:any,friendship:any}>();const friendship=ref(props.friendship);async function add(){const{data}=await axios.post(`/users/${props.profileUser.id}/friendships`);friendship.value=data.data}async function respond(action:string){const{data}=await axios.post(`/friendships/${friendship.value.id}`,{action});friendship.value=data.data}</script>
<template><Head :title="profileUser.name"/><AuthenticatedLayout><div class="mx-auto max-w-4xl px-4 pb-8"><div class="h-56 rounded-b-2xl bg-gradient-to-br from-indigo-400 to-cyan-300" :style="profileUser.cover_photo_url?{backgroundImage:`url(${profileUser.cover_photo_url})`,backgroundSize:'cover',backgroundPosition:'center'}:{}"></div><section class="-mt-14 flex flex-wrap items-end gap-4 border-b bg-white px-6 pb-5"><div class="grid h-28 w-28 place-items-center overflow-hidden rounded-full border-4 border-white bg-indigo-100 text-3xl font-bold text-indigo-700"><img v-if="profileUser.avatar_url" :src="profileUser.avatar_url" class="h-full w-full object-cover">{{profileUser.avatar_url?'':profileUser.name[0]}}</div><div class="pb-1"><h1 class="text-2xl font-bold">{{profileUser.name}}</h1><p class="text-slate-500">@{{profileUser.username}}</p></div><div class="mb-1 ml-auto" v-if="profileUser.id!==$page.props.auth.user.id"><button v-if="!friendship" @click="add" class="rounded-lg bg-indigo-600 px-4 py-2 text-sm font-semibold text-white">Add friend</button><button v-else-if="friendship.status==='pending'&&friendship.receiver_id===$page.props.auth.user.id" @click="respond('accept')" class="rounded-lg bg-indigo-600 px-4 py-2 text-sm font-semibold text-white">Accept request</button><span v-else class="rounded-lg bg-slate-100 px-4 py-2 text-sm">{{friendship.status==='accepted'?'Friends':'Request pending'}}</span></div></section><div class="mx-auto max-w-2xl"><h2 class="mt-6 text-lg font-bold">Posts</h2><article v-for="post in posts.data" :key="post.id" class="mt-4 rounded-2xl bg-white p-4 shadow-sm ring-1 ring-slate-200"><div class="font-semibold">{{post.author.name}}</div><p class="mt-2 whitespace-pre-wrap">{{post.content}}</p><div v-for="media in post.media" :key="media.id" class="mt-3"><img v-if="media.type==='image'" :src="media.url" class="max-h-96 w-full rounded-xl object-cover"><video v-else :src="media.url" controls class="w-full rounded-xl"></video></div><p class="mt-3 text-sm text-slate-500">{{post.comments_count}} comments · {{post.shares_count}} shares</p></article><p v-if="!posts.data.length" class="mt-5 rounded-xl bg-white p-6 text-center text-slate-500">No posts available.</p></div></div></AuthenticatedLayout></template>
